using System;
using System.Collections.Generic;
using System.Runtime.Serialization;
namespace WindowsOptimizerForAll {
 public sealed class TweakItem { public string Name {get;set;} public string Description {get;set;} public Action Apply {get;set;} public bool IsSelected {get;set;} public List<TrackedRegistryValue> TrackedSettings {get;set;}=new List<TrackedRegistryValue>(); public override string ToString(){return Localization.T(Name)+" — "+Localization.T(Description);} }
 public sealed class TrackedRegistryValue { public string Hive {get;set;} public string Key {get;set;} public string Name {get;set;} public TrackedRegistryValue(){} public TrackedRegistryValue(string hive,string key,string name){Hive=hive;Key=key;Name=name;} }
 [DataContract] public sealed class ChangeJournalEntry { [DataMember] public string Id {get;set;} [DataMember] public string Name {get;set;} [DataMember] public string Description {get;set;} [DataMember] public string AppliedAtUtc {get;set;} [DataMember] public bool Reversible {get;set;} [DataMember] public bool Restored {get;set;} [DataMember] public string Status {get;set;} [DataMember] public List<RegistryValueSnapshot> Before {get;set;}=new List<RegistryValueSnapshot>(); [DataMember] public List<RegistryValueSnapshot> After {get;set;}=new List<RegistryValueSnapshot>(); }
 [DataContract] public sealed class RegistryValueSnapshot { [DataMember] public string Hive {get;set;} [DataMember] public string Key {get;set;} [DataMember] public string Name {get;set;} [DataMember] public bool Exists {get;set;} [DataMember] public string Kind {get;set;} [DataMember] public string Value {get;set;} }
 public sealed class SoftwareItem { public string Name {get;set;} public string Description {get;set;} public string Url {get;set;} public string Arguments {get;set;} public bool IsSelected {get;set;} public bool IsInstalled {get;set;} public bool IsAvailableForInstall {get{return IsSupported&&!IsInstalled;}} public string StatusNote {get{return IsInstalled?Localization.T("Уже установлено — будет пропущено"):Localization.T(CompatibilityNote);}} public string Category {get;set;} public string PackageId {get;set;} public bool UseWinget {get;set;} public bool SupportsCustomPath {get;set;} public bool IsSupported {get;set;} public string CompatibilityNote {get;set;} public string FileExtension {get;set;} public string ExpectedSha256 {get;set;} public string[] AllowedHostSuffixes {get;set;} public override string ToString(){return Localization.T(Name)+" ("+Localization.T(Description)+")"+(IsInstalled?" — "+Localization.T("уже установлено; пропускается"):"");} }
 public sealed class AppRemovalItem { public string Name {get;set;} public string PackageId {get;set;} public string Effect {get;set;} public bool IsInstalled {get;set;} public bool IsSelected {get;set;} public string StatusNote {get{return IsInstalled?Localization.T("Будет удалено только для текущего пользователя Windows."):Localization.T("Не установлено для текущего пользователя.");}} public override string ToString(){return Localization.T(Name)+" ("+Localization.T(Effect)+")"+(IsInstalled?"":" — "+Localization.T("не установлено"));} }
 public sealed class DriverDownloadResult { public int AvailableCount {get;set;} public int DownloadedCount {get;set;} public string[] Titles {get;set;} public string ResultMessage {get;set;} }
}
